// Keyed totals: sums signed 64-bit values by key and answers queries.
//
// Input is handled as raw bytes so that keys compare byte-for-byte (no
// Unicode normalisation or replacement of malformed sequences) and are echoed
// back exactly as they appeared.

const MIN = -(1n << 63n);
const MAX = (1n << 63n) - 1n;

type Total = bigint | "overflow";

/** Maps each byte to one UTF-16 code unit, giving a byte-exact string key. */
function bytesToKey(bytes: Uint8Array): string {
  let s = "";
  const CHUNK = 8192;
  for (let i = 0; i < bytes.length; i += CHUNK) {
    s += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
  }
  return s;
}

function keyToBytes(key: string): Uint8Array {
  const out = new Uint8Array(key.length);
  for (let i = 0; i < key.length; i++) out[i] = key.charCodeAt(i);
  return out;
}

/** Splits into lines on LF, dropping a trailing CR from each line. */
function splitLines(data: Uint8Array): Uint8Array[] {
  const lines: Uint8Array[] = [];
  let start = 0;
  for (let i = 0; i <= data.length; i++) {
    if (i === data.length || data[i] === 0x0a) {
      if (i === data.length && start === data.length) break; // trailing newline
      let end = i;
      if (end > start && data[end - 1] === 0x0d) end--;
      lines.push(data.subarray(start, end));
      start = i + 1;
    }
  }
  return lines;
}

const VALUE_RE = /^[+-]?[0-9]+$/;

/** Computes the output bytes for the given input file contents. */
export function run(input: Uint8Array): Uint8Array {
  let data = input;
  if (
    data.length >= 3 && data[0] === 0xef && data[1] === 0xbb &&
    data[2] === 0xbf
  ) {
    data = data.subarray(3); // UTF-8 byte order mark
  }

  const lines = splitLines(data);
  let sep = lines.findIndex((l) => l.length === 0);
  if (sep === -1) sep = lines.length;

  const totals = new Map<string, Total>();
  for (let i = 0; i < sep; i++) {
    const line = bytesToKey(lines[i]);
    const space = line.indexOf(" ");
    if (space <= 0) continue; // malformed record: no key or no value
    const key = line.slice(0, space);
    const text = line.slice(space + 1).trim();
    if (!VALUE_RE.test(text)) continue;
    const value = BigInt(text);

    const prev = totals.get(key);
    if (prev === "overflow") continue;
    const next = (prev ?? 0n) + value;
    totals.set(
      key,
      next < MIN || next > MAX || value < MIN || value > MAX
        ? "overflow"
        : next,
    );
  }

  const parts: Uint8Array[] = [];
  const enc = new TextEncoder();
  let size = 0;
  for (let i = sep + 1; i < lines.length; i++) {
    if (lines[i].length === 0) continue; // stray blank lines carry no query
    const key = bytesToKey(lines[i]);
    const total = totals.get(key);
    const suffix = enc.encode(
      "=" + (total === undefined ? "absent" : total.toString()) + "\n",
    );
    const k = keyToBytes(key);
    parts.push(k, suffix);
    size += k.length + suffix.length;
  }

  const out = new Uint8Array(size);
  let off = 0;
  for (const p of parts) {
    out.set(p, off);
    off += p.length;
  }
  return out;
}

function writeAll(bytes: Uint8Array): void {
  let off = 0;
  while (off < bytes.length) {
    off += Deno.stdout.writeSync(bytes.subarray(off));
  }
}

if (import.meta.main) {
  const path = Deno.args[0];
  if (path === undefined) {
    console.error("usage: deno run --allow-read main.ts <input-file>");
    Deno.exit(2);
  }
  writeAll(run(Deno.readFileSync(path)));
}

