import { assertEquals } from "jsr:@std/assert@1";
import { run } from "./main.ts";

const enc = new TextEncoder();
const dec = new TextDecoder();
const go = (s: string) => dec.decode(run(enc.encode(s)));

Deno.test("basic totals and absent", () => {
  assertEquals(go("a 1
b 2
a 3

a
b
c
"), "a=4
b=2
c=absent
");
});

Deno.test("empty input produces nothing", () => {
  assertEquals(go(""), "");
  assertEquals(go("
"), "");
});

Deno.test("records without queries", () => {
  assertEquals(go("a 1

"), "");
  assertEquals(go("a 1
"), "");
});

Deno.test("queries without records", () => {
  assertEquals(go("
x
"), "x=absent
");
});

Deno.test("64-bit extremes", () => {
  assertEquals(
    go("a 9223372036854775807
b -9223372036854775808

a
b
"),
    "a=9223372036854775807
b=-9223372036854775808
",
  );
});

Deno.test("overflow is sticky and in record order", () => {
  assertEquals(
    go("a 9223372036854775807
a 1
a -5

a
"),
    "a=overflow
",
  );
  assertEquals(
    go("a 9223372036854775807
a -5
a 1

a
"),
    "a=9223372036854775803
",
  );
  assertEquals(go("a -9223372036854775808
a -1

a
"), "a=overflow
");
});

Deno.test("unicode keys compare by bytes", () => {
  // precomposed vs decomposed é are different keys
  assertEquals(
    go("é 1
é 2
日本 5

é
é
日本
"),
    "é=1
é=2
日本=5
",
  );
});

Deno.test("CRLF line endings and repeated queries", () => {
  assertEquals(go("a 1
a 2

a
a
"), "a=3
a=3
");
});

Deno.test("no trailing newline", () => {
  assertEquals(go("a -1

a"), "a=-1
");
});

